      \vspace{0.42cm}
      \hbox to \textwidth { {#4 \hfill Scribes:\hspace{0.08cm}#5} } \vspace{0.25cm}
    }
  }
  \end{center}
  \vspace*{4mm}
}

%Create a draft notice command to signal when the scribe notes are not finished.
\newcommand{\draftnotice}
{
    \vbox to 0.25in
